find:
if not ts:
    return False
try:
    d = parse_ts(ts)
except Exception:
    return False
return start <= d < end

replace:
if not ts:
    return False
try:
    d = parse_ts(ts)
except Exception:
    # A stamp we cannot parse is still a real observation. Dropping it shrinks
    # the numerator AND the denominator, so keep it in the current window.
    return True
return start <= d < end
